def find_minimal_edit(s_in, s_out):
    """Find the minimal change from s_in to s_out"""
    # Find first difference
    min_len = min(len(s_in), len(s_out))

    # Look for insertion/deletion
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Found a difference at position i
            # Check if it's insertion or deletion by looking ahead
            # Try to find the longest matching prefix/suffix
            return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of the other
    if len(s_in) < len(s_out):
        # Insertion case
        return (s_in[-1] if s_in else "", s_out[len(s_in):], len(s_in)-1)
    elif len(s_in) > len(s_out):
        # Deletion case  
        return (s_in[len(s_out):], s_out[-1] if s_out else "", len(s_out))
    else:
        # Strings are identical
        return ("", "", -1)

